import React, { useEffect, useState } from 'react';
import { AlertTriangle, Bot, CheckCircle2, ChevronLeft, ExternalLink, Network, RadioTower, RefreshCw, Search, UserCog, UserSquare2, UsersRound } from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import apiServerClient from '@/lib/apiServerClient';
import pb from '@/lib/pocketbaseClient';

const request = async (path, options = {}) => {
  const response = await apiServerClient.fetch(path, { ...options, headers: { Authorization: `Bearer ${pb.authStore.token}`, 'Content-Type': 'application/json' } });
  const payload = await apiServerClient.readJson(response);
  if (!response.ok || !payload.ok) throw new Error(payload.error || `HTTP ${response.status}`);
  return payload;
};

const MoonbotGroupsManager = ({ groups = [], entityType = 'group' }) => {
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState(null);
  const [detail, setDetail] = useState(null);
  const [comparison, setComparison] = useState(null);
  const [ads, setAds] = useState(null);
  const [rss, setRss] = useState(null);
  const [rssUrl, setRssUrl] = useState('');
  const [rssTitle, setRssTitle] = useState('');
  const [adText, setAdText] = useState('');
  const [adTarget, setAdTarget] = useState('');
  const [adWhen, setAdWhen] = useState('');
  const [error, setError] = useState('');
  const [captchaPreview, setCaptchaPreview] = useState(null);
  const [banningUsers, setBanningUsers] = useState(new Set());
  const [appealSubmittingUsers, setAppealSubmittingUsers] = useState(new Set());
  const [autoAppealedUsers, setAutoAppealedUsers] = useState([]);
  const [listedGroups, setListedGroups] = useState(groups);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(groups.length);
  const [totalPages, setTotalPages] = useState(1);
  const [loadingList, setLoadingList] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [photoUrl, setPhotoUrl] = useState('');
  const [requiredChannelSearch, setRequiredChannelSearch] = useState('');
  const [paidSubscriptions, setPaidSubscriptions] = useState(null);
  const [paidSubscriptionName, setPaidSubscriptionName] = useState('Acceso mensual');
  const [paidSubscriptionPrice, setPaidSubscriptionPrice] = useState('100');
  const isChannelView = entityType === 'channel';
  const entityLabel = isChannelView ? 'canal' : 'grupo';
  const entityLabelPlural = isChannelView ? 'canales' : 'grupos';
  const parsePositiveInt = (value, fallback = 5) => {
    const parsed = Number.parseInt(String(value || '').trim(), 10);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
  };
  const parseIdList = (value, fallback = []) =>
    String(value || '')
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)
      .filter((item) => /^-?\d+$/.test(item))
      .filter(Boolean);
  const captchaGlobalBanThreshold = parsePositiveInt(detail?.join_config?.captcha_global_ban_threshold, 5);
  const captchaAppeals = Array.isArray(detail?.captcha_appeals) ? detail.captcha_appeals : [];
  const persistentCaptchaFailures = Array.isArray(detail?.captcha_fail_users)
    ? detail.captcha_fail_users
    : Array.isArray(detail?.join_config?.persistent_fail_users)
      ? detail.join_config.persistent_fail_users
      : [];
  const persistentCaptchaUsers = persistentCaptchaFailures
    .map((item) => ({
      ...item,
      userId: String(item?.user_id || item?.telegram_id || item?.id || '').trim(),
      failedAttempts: Number.parseInt(String(item?.failed_attempts || item?.failures || item?.attempts || 0), 10),
      userLabel: item?.name || item?.username || item?.title || item?.user_name || null,
    }))
    .filter((item) => Number.isFinite(item.failedAttempts) && item.failedAttempts >= captchaGlobalBanThreshold)
    .filter((item) => item.userId);
  const persistentCaptchaSignature = persistentCaptchaUsers
    .map((item) => `${item.userId}:${item.failedAttempts}`)
    .sort()
    .join('|');
  const adminDetection = (detail?.administrators || [])
    .map((admin) => ({
      ...admin,
      _adminUserId: String(admin?.user_id || '').trim(),
      _isBot: Boolean(admin?.is_bot || admin?.is_bot_like || admin?.bot || admin?.type === 'bot' || admin?.source_type === 'bot'),
      _isUserbot: Boolean(admin?.is_userbot || admin?.source_type === 'userbot' || admin?.type === 'userbot' || /user.?bot/i.test(String(admin?.username || ''))),
      _isCreator: admin?.status === 'creator',
    }))
    .filter((admin) => admin._adminUserId);
  const totalAdmins = adminDetection.length;
  const totalBotLikeAdmins = adminDetection.filter((admin) => admin._isBot || admin._isUserbot).length;
  useEffect(() => {
    if (selected) return undefined;
    const timer = window.setTimeout(async () => {
      setLoadingList(true); setError('');
      try { const payload = await request(`/moonbot-admin/groups?q=${encodeURIComponent(query)}&type=${entityType}&page=${page}&per_page=40`); setListedGroups(payload.groups || []); setTotal(payload.total || 0); setPage(payload.page || 1); setTotalPages(payload.total_pages || 1); }
      catch (cause) { setError(cause.message); }
      finally { setLoadingList(false); }
    }, 250);
    return () => window.clearTimeout(timer);
  }, [entityType, page, query, selected]);
  useEffect(() => {
    if (!selected?.id) { setPhotoUrl(''); return undefined; }
    let active = true;
    let objectUrl = '';
    apiServerClient.fetch(`/moonbot-admin/groups/${selected.id}/photo`, {
      headers: { Authorization: `Bearer ${pb.authStore.token}` },
    }).then(async (response) => {
      if (!response.ok) return;
      objectUrl = URL.createObjectURL(await response.blob());
      if (active) setPhotoUrl(objectUrl);
    }).catch(() => {});
    return () => { active = false; if (objectUrl) URL.revokeObjectURL(objectUrl); setPhotoUrl(''); };
  }, [selected?.id, selected?.synced_at]);
  const open = async (group) => { setSelected(group); setDetail(null); setComparison(null); setAds(null); setRss(null); setPaidSubscriptions(null); setCaptchaPreview(null); setRequiredChannelSearch(''); setError(''); try { const jobs = [request(`/moonbot-admin/groups/${group.id}`), request(`/moonbot-admin/groups/${group.id}/rss`)]; if (String(group.ctype).toLowerCase() === 'channel') jobs.push(request(`/moonbot-admin/groups/${group.id}/paid-subscriptions`)); const [groupDetail, rssData, subscriptions] = await Promise.all(jobs); setDetail(groupDetail); setRss(rssData); if (subscriptions) setPaidSubscriptions(subscriptions); } catch (cause) { setError(cause.message); } };
  useEffect(() => {
    setAutoAppealedUsers([]);
  }, [selected?.id]);

  useEffect(() => {
    if (!selected?.id || !detail || !persistentCaptchaUsers.length || detail.join_config?.auto_appeal_captcha_failures === false) return;
    const groupKey = String(selected.id);
    const listToAutoAppeal = persistentCaptchaUsers
      .filter((item) => !autoAppealedUsers.includes(`${groupKey}:${item.userId}`))
      .slice(0, 8);
    if (!listToAutoAppeal.length) return;
    // Reserva el lote antes de iniciar peticiones. Las respuestas actualizan
    // `detail` y vuelven a renderizar; sin esta reserva se podían duplicar
    // apelaciones que ya estaban en curso.
    const reservedKeys = listToAutoAppeal.map((item) => `${groupKey}:${item.userId}`);
    setAutoAppealedUsers((current) => [...new Set([...current, ...reservedKeys])]);

    const runAutoAppeal = async () => {
      for (const item of listToAutoAppeal) {
        await requestCaptchaAppeal(item.userId, item.userLabel || `Usuario ${item.userId}`, true);
      }
    };
    runAutoAppeal();
  }, [detail?.id, detail?.captcha_fail_users, detail?.join_config?.persistent_fail_users, detail?.join_config?.auto_appeal_captcha_failures, selected?.id, persistentCaptchaSignature, autoAppealedUsers]);

  const groupAction = async (action, sourceId, extra = {}) => {
    try {
      const payload = await request(`/moonbot-admin/groups/${selected.id}`, { method: 'POST', body: JSON.stringify({ action, source_id: sourceId, ...extra }) });
      if (payload.config) setDetail((current) => ({ ...current, config: payload.config }));
      if (payload.join_config) setDetail((current) => ({ ...current, join_config: payload.join_config }));
      if (payload.captcha_job) setDetail((current) => ({ ...current, captcha_job: payload.captcha_job }));
      if (payload.captcha_preview) setCaptchaPreview(payload.captcha_preview);
      if (payload.command_menu) setDetail((current) => ({ ...current, command_menu: payload.command_menu }));
      if (payload.comparison) setComparison(payload.comparison);
      if (payload.group) { setSelected((current) => ({ ...current, ...payload.group })); if (action === 'directory_review') setDetail((current) => ({ ...current, directory: { ...(current?.directory || {}), ...payload.group } })); }
      if (payload.community) setDetail((current) => ({ ...current, community: payload.community }));
    } catch (cause) { setError(cause.message); }
  };
  const loadAds = async () => { try { setAds(await request(`/moonbot-admin/groups/${selected.id}/ads`)); } catch (cause) { setError(cause.message); } };
  const adAction = async (action, extra = {}) => { try { const payload = await request(`/moonbot-admin/groups/${selected.id}/ads`, { method: 'POST', body: JSON.stringify({ action, ...extra }) }); setAds(payload); } catch (cause) { setError(cause.message); } };
  const rssAction = async (action, extra = {}) => { try { const payload = await request(`/moonbot-admin/groups/${selected.id}/rss`, { method: 'POST', body: JSON.stringify({ action, ...extra }) }); setRss(payload); if (action === 'add') { setRssUrl(''); setRssTitle(''); } return payload; } catch (cause) { setError(cause.message); return null; } };
  const paidSubscriptionAction = async (action, extra = {}) => { try { const payload = await request(`/moonbot-admin/groups/${selected.id}/paid-subscriptions`, { method: 'POST', body: JSON.stringify({ action, ...extra }) }); setPaidSubscriptions(payload); return payload; } catch (cause) { setError(cause.message); return null; } };
  const configureRss = async (feed) => {
    const title = window.prompt('Nombre visible de la fuente', feed.title || ''); if (title === null) return;
    const include = window.prompt('Palabras que debe incluir, separadas por comas (vacío = todas)', (feed.include_keywords || []).join(', ')); if (include === null) return;
    const exclude = window.prompt('Palabras que se deben excluir', (feed.exclude_keywords || []).join(', ')); if (exclude === null) return;
    const messageThreadId = window.prompt('ID del tema de Telegram (vacío = chat principal)', feed.message_thread_id || ''); if (messageThreadId === null) return;
    const pollInterval = window.prompt('Frecuencia en minutos (5-1440)', feed.poll_interval_minutes || 15); if (pollInterval === null) return;
    const maximum = window.prompt('Máximo de entradas por ciclo (1-10)', feed.max_entries_per_cycle || 3); if (maximum === null) return;
    const failures = window.prompt('Pausar tras cuántos fallos (1-20)', feed.pause_after_failures || 5); if (failures === null) return;
    const quietStart = window.prompt('Inicio del horario silencioso UTC (0-23, vacío = desactivado)', feed.quiet_start_utc ?? ''); if (quietStart === null) return;
    const quietEnd = window.prompt('Fin del horario silencioso UTC (0-23, vacío = desactivado)', feed.quiet_end_utc ?? ''); if (quietEnd === null) return;
    const template = window.prompt('Plantilla: usa {title}, {url} y opcionalmente {source}', feed.template || '?? **{title}**\n{url}'); if (template === null) return;
    const saved = await rssAction('configure', { feed_id: feed.id, title, include_keywords: include, exclude_keywords: exclude, message_thread_id: messageThreadId, poll_interval_minutes: pollInterval, max_entries_per_cycle: maximum, pause_after_failures: failures, quiet_start_utc: quietStart, quiet_end_utc: quietEnd, template });
    if (saved && window.confirm('Configuración guardada. ¿Comprobar y publicar ahora?')) await rssAction('run_now', { feed_id: feed.id });
    if (saved && window.confirm('¿Quieres reiniciar el cursor? La siguiente lectura inicializará la fuente sin publicar históricos.')) await rssAction('reset_cursor', { feed_id: feed.id });
  };
  const refreshTelegram = async () => {
    setRefreshing(true); setError('');
    try {
      const payload = await request(`/moonbot-admin/groups/${selected.id}`, { method: 'POST', body: JSON.stringify({ action: 'refresh_telegram' }) });
      if (payload.group) setSelected((current) => ({ ...current, ...payload.group }));
      setDetail(await request(`/moonbot-admin/groups/${selected.id}`));
    } catch (cause) { setError(cause.message); }
    finally { setRefreshing(false); }
  };
  const banGlobalCaptchaUser = async (userId, userLabel = '') => {
    if (!userId || banningUsers.has(userId)) return;
    const reason = window.prompt(`Motivo del ban global para ${userLabel || `Usuario ${userId}`}`, 'Fallos persistentes de captcha');
    if (reason === null) return;

    setBanningUsers((current) => new Set(current).add(userId));
    try {
      const response = await request(`/moonbot-admin/users/${encodeURIComponent(userId)}`, {
        method: 'POST',
        body: JSON.stringify({
          action: 'ban_global',
          reason: reason || 'Fallos persistentes de captcha',
        }),
      });
      if (!response || response.ok === false) throw new Error(response?.error || 'No se pudo ejecutar el baneo global');
    } catch (cause) {
      setError(cause.message);
    } finally {
      setBanningUsers((current) => {
        const next = new Set(current);
        next.delete(userId);
        return next;
      });
    }
  };
  const requestCaptchaAppeal = async (userId, userLabel = '', auto = false) => {
    if (!userId || appealSubmittingUsers.has(userId)) return;
    const reason = auto
      ? 'Fallos repetidos en captcha, solicitud automática.'
      : window.prompt(`Solicitar apelación de captcha para ${userLabel || `Usuario ${userId}`}`, 'Fallos repetidos en el captcha.');
    if (!auto && reason === null) return;

    setAppealSubmittingUsers((current) => new Set(current).add(userId));
    setError('');
    try {
      const payload = {
        action: 'request_captcha_appeal',
        reason: reason || 'Solicitud de apelación de captcha',
        group_id: selected?.id || '',
        source: 'captcha',
      };
      try {
        await request(`/moonbot-admin/users/${encodeURIComponent(userId)}`, { method: 'POST', body: JSON.stringify(payload) });
      } catch {
        await request(`/moonbot-admin/users/${encodeURIComponent(userId)}`, {
          method: 'POST',
          body: JSON.stringify({ ...payload, action: 'request_appeal', appeal_type: 'captcha' }),
        });
      }
      const fresh = await request(`/moonbot-admin/groups/${selected.id}`);
      setDetail(fresh);
    } catch (cause) {
      setError(cause.message);
    } finally {
      setAppealSubmittingUsers((current) => {
        const next = new Set(current);
        next.delete(userId);
        return next;
      });
    }
  };

  if (!selected) { const EntityIcon = isChannelView ? RadioTower : UsersRound; return <Card className="mt-8 border-violet-500/20"><CardHeader><CardTitle className="flex items-center gap-2"><EntityIcon className="h-5 w-5 text-violet-600" />Administración de {entityLabelPlural}</CardTitle><CardDescription>{total} {entityLabelPlural} vinculados con bots activos · búsqueda sobre todo el inventario.</CardDescription></CardHeader><CardContent>{error && <div className="mb-4 rounded-xl border border-amber-500/30 bg-amber-500/10 p-3 text-sm">{error}</div>}<div className="relative mb-4"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pl-9" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder={`Buscar ${entityLabel} por nombre, ID o bot`} /></div><div className={`grid gap-3 md:grid-cols-2 ${loadingList ? 'opacity-60' : ''}`}>{listedGroups.map((group) => <button key={group.id} onClick={() => open(group)} className="rounded-xl border p-4 text-left hover:border-violet-500/50 hover:bg-muted/30"><div className="flex items-start justify-between gap-2"><p className="font-semibold">{group.name || `${isChannelView ? 'Canal' : 'Grupo'} ${group.id}`}</p><span className="flex gap-1"><Badge variant="outline">{isChannelView ? 'Canal' : 'Grupo'}</Badge>{group.community?.active && <Badge><Network className="mr-1 h-3 w-3"/>Comunidad</Badge>}</span></div><p className="text-xs text-muted-foreground">{group.username && group.username !== group.id ? `@${String(group.username).replace(/^@/, '')} · ` : ''}{group.id}</p><div className="mt-2 flex flex-wrap gap-1">{(group.bots?.length ? group.bots : group.bot_username ? [{ username: group.bot_username }] : []).map((bot) => <Badge key={`${group.id}-${bot.id || bot.username}`} variant="secondary">@{bot.username}</Badge>)}</div>{group.synced_at && <p className="mt-2 text-xs text-muted-foreground">Sincronizado {new Date(group.synced_at).toLocaleString()}</p>}</button>)}</div>{!loadingList && !listedGroups.length && <p className="rounded-xl border border-dashed p-6 text-center text-sm text-muted-foreground">No hay {entityLabelPlural} que coincidan con la búsqueda.</p>}<div className="mt-4 flex items-center justify-between"><Button size="sm" variant="outline" disabled={loadingList || page <= 1} onClick={() => setPage((value) => value - 1)}>Anterior</Button><span className="text-xs text-muted-foreground">Página {page} de {totalPages}</span><Button size="sm" variant="outline" disabled={loadingList || page >= totalPages} onClick={() => setPage((value) => value + 1)}>Siguiente</Button></div></CardContent></Card>; }

  return <Card className="mt-8 border-violet-500/20"><CardHeader><Button variant="ghost" className="mb-2 w-fit" onClick={() => setSelected(null)}><ChevronLeft className="mr-2 h-4 w-4" />Volver a {entityLabelPlural}</Button><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex items-center gap-3">{photoUrl ? <img src={photoUrl} alt="" className="h-14 w-14 rounded-full border object-cover" /> : <div className="flex h-14 w-14 items-center justify-center rounded-full border bg-muted text-lg font-semibold">{String(selected.name || '?').slice(0, 1).toUpperCase()}</div>}<div><CardTitle>{selected.name}</CardTitle><CardDescription>{isChannelView ? 'Canal' : 'Grupo'} · ID {selected.id}{selected.synced_at ? ` · sincronizado ${new Date(selected.synced_at).toLocaleString()}` : ''}</CardDescription></div></div><Button variant="outline" disabled={refreshing} onClick={refreshTelegram}><RefreshCw className={`mr-2 h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />{refreshing ? 'Sincronizando' : 'Actualizar desde Telegram'}</Button></div></CardHeader><CardContent className="space-y-5">
    {error && <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 p-4 text-sm">{error}</div>}
    {detail && <>
      <section className={`rounded-xl border p-4 ${detail.permissions.healthy ? 'border-emerald-500/30 bg-emerald-500/10' : 'border-amber-500/30 bg-amber-500/10'}`}>
        <h3 className="flex items-center gap-2 font-semibold">{detail.permissions.healthy ? <CheckCircle2 className="h-5 w-5" /> : <AlertTriangle className="h-5 w-5" />}Permisos del bot</h3>
        <p className="mt-2 text-sm">{detail.permissions.healthy ? 'Todos los permisos esenciales están disponibles.' : `Faltan: ${detail.permissions.missing.map((item) => item.label).join(', ')}`}</p>
        {detail.repair_steps?.length > 0 && <ol className="mt-3 list-inside list-decimal text-sm">{detail.repair_steps.map((step) => <li key={step}>{step}</li>)}</ol>}
        <details className="mt-3 text-sm"><summary>Historial efectivo de permisos ({detail.permission_history?.length || 0})</summary><div className="mt-2 max-h-52 space-y-2 overflow-auto">{detail.permission_history?.map((item) => <div key={item.id} className="rounded-lg border bg-background/70 p-2 text-xs"><b>@{item.bot_username || 'MoonBot'}</b> · {item.healthy ? 'Permisos correctos' : `Faltan: ${item.missing?.map((entry) => entry.label).join(', ')}`}<p className="text-muted-foreground">{new Date(item.detected_at).toLocaleString()} · comprobado por {item.actor || 'sistema'}</p></div>)}{!detail.permission_history?.length && <p className="text-muted-foreground">La primera comprobación creará el historial.</p>}</div></details>
      </section>
      {isChannelView && <section className="rounded-xl border border-cyan-500/30 bg-cyan-500/5 p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-semibold">Directorio público de canales</h3><p className="mt-1 text-sm text-muted-foreground">Solo los canales aprobados aparecen en canales.todosobreall.tech.</p></div><Badge variant={detail.directory?.directory_status === 'approved' ? 'default' : 'outline'}>{detail.directory?.directory_status === 'approved' ? 'Aprobado y visible' : detail.directory?.directory_status === 'pending' ? 'Pendiente de revisión' : detail.directory?.directory_status === 'rejected' ? 'Rechazado' : 'No revisado'}</Badge></div><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" onClick={() => groupAction('directory_review', null, { status: 'approved' })}>Aprobar y publicar</Button><Button size="sm" variant="destructive" onClick={() => groupAction('directory_review', null, { status: 'rejected' })}>Rechazar y ocultar</Button></div>{detail.directory?.directory_submitted_at && <p className="mt-2 text-xs text-muted-foreground">Solicitud: {new Date(detail.directory.directory_submitted_at).toLocaleString()}</p>}</section>}
      <section className="rounded-xl border border-sky-500/30 bg-sky-500/5 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="flex items-center gap-2 font-semibold"><Network className="h-5 w-5 text-sky-600"/>Comunidad de Telegram</h3><p className="mt-1 text-sm text-muted-foreground">Moonbot detecta automáticamente la comunidad real mediante Bot API 10.2 y agrupa sus chats.</p></div><Button size="sm" variant="outline" onClick={() => groupAction('scan_community')}>Detectar en todos</Button></div>{detail.community?.detected ? <div className="mt-3 space-y-3"><div className="rounded-lg border bg-background p-3"><b>{detail.community.current?.community?.title || detail.community.current?.community?.name || `Comunidad ${detail.community.current?.community_id}`}</b><p className="text-xs text-muted-foreground">{detail.community.members?.length || 0} chats detectados · ID {detail.community.current?.community_id}</p></div><div><p className="mb-2 text-xs font-semibold uppercase text-muted-foreground">Chats ya incluidos</p><div className="flex flex-wrap gap-2">{detail.community.members?.map((item) => <Badge key={item.id} variant="secondary">{item.ctype === 'channel' ? 'Canal' : 'Grupo'} · {item.name}</Badge>)}</div></div><details className="rounded-lg border bg-background p-3"><summary className="cursor-pointer text-sm font-semibold">Añadir otros chats administrados ({detail.community.candidates?.length || 0})</summary><p className="my-2 text-xs text-muted-foreground">Telegram exige confirmar la incorporación desde sus ajustes. Abre cada chat, entra en su comunidad y vuelve a pulsar «Detectar en todos».</p><div className="max-h-64 space-y-2 overflow-auto">{detail.community.candidates?.map((item) => <div key={item.id} className="flex items-center justify-between gap-2 rounded-lg border p-2 text-sm"><span><b>{item.name}</b><small className="block text-muted-foreground">{item.ctype === 'channel' ? 'Canal' : 'Grupo'} · {item.id}</small></span>{item.telegram_url ? <Button size="sm" asChild><a href={item.telegram_url} target="_blank" rel="noreferrer">Abrir Telegram<ExternalLink className="ml-1 h-3 w-3"/></a></Button> : <Badge variant="outline">Privado</Badge>}</div>)}</div>{!detail.community.candidates?.length && <p className="mt-2 text-sm text-muted-foreground">Todos los chats compatibles detectados ya están incluidos.</p>}</details></div> : <div className="mt-3 rounded-lg border border-dashed bg-background p-3 text-sm"><p>Este chat todavía no pertenece a una comunidad detectada.</p><p className="mt-1 text-xs text-muted-foreground">Créala o añade este chat desde Telegram y pulsa «Actualizar desde Telegram». La asociación quedará registrada automáticamente.</p></div>}</section>
      <section className="rounded-xl border p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="flex items-center gap-2 font-semibold"><UserCog className="h-5 w-5" />Equipo administrador</h3>{detail.administrators_checked_at && <span className="text-xs text-muted-foreground">Comprobado {new Date(detail.administrators_checked_at).toLocaleString()}</span>}</div><div className="mt-2 text-sm text-muted-foreground">{totalAdmins > 0 ? <p>{totalAdmins} administrador(es) detectado(s) · {totalBotLikeAdmins} perfil(es) bot/userbot</p> : <p>No hay datos aún.</p>}</div><div className="mt-3 grid gap-2 md:grid-cols-2">{adminDetection.map((admin) => <div key={admin._adminUserId} className="flex items-center justify-between rounded-lg border p-3"><div className="flex items-center gap-2"><div className="rounded-full border p-1">{admin._isUserbot ? <UserSquare2 className="h-4 w-4" /> : admin._isBot ? <Bot className="h-4 w-4" /> : <UserSquare2 className="h-4 w-4 text-muted-foreground" />}</div><div><p className="font-medium">{admin.name || admin.username ? `${admin.name || ''}${admin.username ? ` @${admin.username}` : ''}` : `Usuario ${admin._adminUserId}`}</p><p className="text-xs text-muted-foreground">ID {admin._adminUserId}</p></div></div><div className="flex items-center gap-2">{admin._isUserbot && <Badge variant="outline">Userbot</Badge>}{admin._isBot && <Badge variant="outline">Bot</Badge>}{admin._isCreator ? <Badge variant="default">Propietario</Badge> : <Badge variant="secondary">Administrador</Badge>}</div></div>)}</div>{!detail.administrators?.length && <p className="mt-3 text-sm text-muted-foreground">Pulsa «Actualizar desde Telegram» para obtener el equipo administrador.</p>}</section>
      <div className="grid grid-cols-3 gap-3">{Object.entries(detail.activity).map(([key, value]) => <div key={key} className="rounded-xl border p-3 text-center"><b className="text-xl">{value}</b><p className="text-xs text-muted-foreground">{key.replaceAll('_', ' ')}</p></div>)}</div>
      <section className="rounded-xl border p-4">
        <h3 className="font-semibold">Canales obligatorios locales</h3>
        <p className="my-2 text-sm text-muted-foreground">Se exigen solo en este grupo y se suman a los canales globales configurados por el master.</p>
        <div className="flex flex-wrap gap-2">{(detail.join_config?.required_channels || []).map((channel) => <Badge key={channel} variant="outline" className="gap-2">@{channel}<button type="button" aria-label={`Quitar ${channel}`} onClick={() => groupAction('save_join_config', null, { required_channels: (detail.join_config?.required_channels || []).filter((item) => item !== channel) })}>×</button></Badge>)}{!(detail.join_config?.required_channels || []).length && <Badge variant="outline">Sin configurar</Badge>}</div>
        <div className="mt-3 flex flex-wrap gap-2"><Button variant="outline" onClick={() => { const current = (detail.join_config?.required_channels || []).map((channel) => `@${channel}`).join(', '); const value = window.prompt('Canales obligatorios separados por comas (máximo 10)', current); if (value !== null) { const channels = [...new Set(value.split(',').map((item) => item.trim().replace(/^@/, '')).filter(Boolean))].slice(0, 10); groupAction('save_join_config', null, { required_channels: channels }); } }}>Editar lista manualmente</Button></div>
        <div className="relative mt-4"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground"/><Input className="pl-9" value={requiredChannelSearch} onChange={(event) => setRequiredChannelSearch(event.target.value)} placeholder="Buscar canal candidato por nombre, @usuario o ID"/></div>
        <div className="mt-3 grid gap-2">{(detail.required_channel_suggestions || []).filter((item) => `${item.title || ''} ${item.username || ''} ${item.chat_id || ''}`.toLowerCase().includes(requiredChannelSearch.trim().toLowerCase())).map((item) => { const selected = (detail.join_config?.required_channels || []).some((channel) => channel.toLowerCase() === item.channel.toLowerCase()); return <div key={item.channel} className={`flex w-full flex-wrap items-center justify-between gap-3 rounded-xl border p-3 text-left ${selected ? 'border-cyan-500 bg-cyan-500/10' : 'hover:bg-muted/60'}`}><div className="flex min-w-0 flex-1 items-center gap-3">{item.photo_url ? <img src={item.photo_url} alt="" className="h-11 w-11 shrink-0 rounded-xl object-cover" loading="lazy"/> : <span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-cyan-500/10"><RadioTower className="h-5 w-5 text-cyan-600"/></span>}<div className="min-w-0"><b className="block truncate">{item.title}</b><p className="truncate text-xs text-muted-foreground">{item.username ? `@${item.username}` : item.chat_id}</p><p className="text-[11px] text-muted-foreground">{item.content_review?.messages_analyzed ? `${item.content_review.messages_analyzed} mensajes analizados · riesgo ${item.content_review.score}/100` : 'Análisis pendiente'}</p></div></div><div className="flex shrink-0 gap-2">{item.join_bot_url ? <Button type="button" variant="outline" size="sm" asChild><a href={item.join_bot_url} target="_blank" rel="noreferrer">Unir bot<ExternalLink className="ml-1 h-3 w-3"/></a></Button> : <Badge variant="outline" className="self-center text-emerald-700">Bot unido</Badge>}<Button type="button" size="sm" variant={selected ? 'secondary' : 'default'} onClick={() => { const current = detail.join_config?.required_channels || []; const next = selected ? current.filter((channel) => channel.toLowerCase() !== item.channel.toLowerCase()) : [...current, item.channel].slice(0, 10); groupAction('save_join_config', null, { required_channels: next }); }}>{selected ? 'Quitar' : '+ Añadir'}</Button></div></div>; })}</div>
        {!(detail.required_channel_suggestions || []).length && <p className="mt-3 text-xs text-muted-foreground">No se detectaron canales candidatos seguros donde esté unido el bot que administra este grupo.</p>}
        {Boolean(requiredChannelSearch) && !(detail.required_channel_suggestions || []).some((item) => `${item.title || ''} ${item.username || ''} ${item.chat_id || ''}`.toLowerCase().includes(requiredChannelSearch.trim().toLowerCase())) && <p className="mt-3 text-xs text-muted-foreground">No hay canales que coincidan con la búsqueda.</p>}
      </section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Acceso con captcha</h3><p className="my-2 text-sm text-muted-foreground">Retira mediante Telegram todos los permisos de envío hasta completar captcha, CAS y suscripciones.</p><div className="flex flex-wrap gap-2"><Button variant={detail.join_config?.mute_until_verified !== false ? 'default' : 'outline'} onClick={() => groupAction('save_join_config', null, { enabled: true, mute_until_verified: detail.join_config?.mute_until_verified === false })}>{detail.join_config?.mute_until_verified !== false ? 'Mute automático activo' : 'Activar mute automático'}</Button><Button variant={detail.join_config?.strict_enforcement ? 'destructive' : 'outline'} onClick={() => groupAction('save_join_config', null, { enabled: true, mute_until_verified: true, strict_enforcement: !detail.join_config?.strict_enforcement })}>{detail.join_config?.strict_enforcement ? 'Captcha estricto activo' : 'Activar modo sin excepciones'}</Button><Button variant={detail.join_config?.reverify_interval_days ? 'default' : 'outline'} onClick={() => groupAction('save_join_config', null, { reverify_interval_days: detail.join_config?.reverify_interval_days ? 0 : 30 })}>{detail.join_config?.reverify_interval_days ? `Automático cada ${detail.join_config.reverify_interval_days} días` : 'Programar cada 30 días'}</Button><Button variant="outline" onClick={() => { const value = window.prompt('IDs de usuarios exentos separados por comas', (detail.join_config?.exempt_user_ids || []).join(', ')); if (value !== null) groupAction('save_join_config', null, { exempt_user_ids: parseIdList(value, detail.join_config?.exempt_user_ids || []) }); }}>Exentos usuarios ({detail.join_config?.exempt_user_ids?.length || 0})</Button><Button variant="outline" onClick={() => { const value = window.prompt('IDs de grupos exentos separados por comas', (detail.join_config?.exempt_group_ids || []).join(', ')); if (value !== null) groupAction('save_join_config', null, { exempt_group_ids: parseIdList(value, detail.join_config?.exempt_group_ids || []) }); }}>Exentos grupos ({detail.join_config?.exempt_group_ids?.length || 0})</Button><Button variant="outline" onClick={() => groupAction('preview_reverify')}>Vista previa</Button><Button variant="destructive" disabled={detail.captcha_job?.status === 'running'} onClick={() => window.confirm('Se silenciará a todos los miembros conocidos hasta que completen el captcha. ¿Continuar?') && groupAction('reverify_all')}>{detail.captcha_job?.status === 'running' ? 'Reverificación en curso' : 'Reverificar a todos'}</Button>{detail.captcha_job?.status === 'running' && <Button variant="outline" onClick={() => groupAction('cancel_reverify')}>Cancelar campaña</Button>}</div>{captchaPreview && <p className="mt-2 text-xs text-blue-600">{captchaPreview.observed} miembros conocidos. {captchaPreview.note}</p>}{detail.join_config?.reverify_interval_days > 0 && <p className="mt-2 text-xs text-blue-600">Próxima campaña estimada: {new Date(((detail.captcha_schedule?.last_run || Math.floor(Date.now() / 1000)) + detail.join_config.reverify_interval_days * 86400) * 1000).toLocaleString()}</p>}{detail.join_config?.strict_enforcement && <p className="mt-2 text-xs text-amber-600">El mute se reaplica y el desafío se reenvía cuando un usuario pendiente intenta escribir.</p>}{detail.captcha_job?.status && <p className="mt-2 text-xs text-muted-foreground">{detail.captcha_job.processed || 0}/{detail.captcha_job.total || 0} procesados · {detail.captcha_job.muted || 0} silenciados · {detail.captcha_job.private_sent || 0} privados entregados · {detail.captcha_job.private_blocked || 0} bloqueados por Telegram</p>}{detail.captcha_history?.length > 0 && <details className="mt-3 text-xs"><summary>Historial de campañas ({detail.captcha_history.length})</summary>{detail.captcha_history.map((item, index) => <p key={`${item.finished_at}-${index}`} className="mt-1 text-muted-foreground">{new Date((item.finished_at || item.started_at) * 1000).toLocaleString()} · {item.status} · {item.muted || 0} silenciados · {item.private_sent || 0} privados</p>)}</details>}{persistentCaptchaUsers.length > 0 && <section className="mt-4 rounded-xl border border-rose-500/30 bg-rose-500/10 p-3"><h3 className="text-sm font-semibold text-rose-700">⚠️ Aviso de fallos persistentes de captcha</h3><p className="mt-2 text-xs text-rose-700">Se detectaron {persistentCaptchaUsers.length} usuario(s) con {captchaGlobalBanThreshold} o más fallos fallidos. Se recomienda evaluación para baneo global.</p><ul className="mt-2 space-y-2 text-xs text-rose-700">{persistentCaptchaUsers.slice(0, 20).map((item) => <li key={item.userId} className="flex flex-wrap items-center justify-between gap-2"><span className="font-medium">{item.userLabel || `Usuario ${item.userId}`}</span><span>ID {item.userId} · {item.failedAttempts} fallos</span><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => requestCaptchaAppeal(item.userId, item.userLabel || `Usuario ${item.userId}`)} disabled={appealSubmittingUsers.has(item.userId)}>{appealSubmittingUsers.has(item.userId) ? 'Enviando...' : 'Solicitar apelación'}</Button><Button size="sm" variant="destructive" onClick={() => banGlobalCaptchaUser(item.userId, item.userLabel || `Usuario ${item.userId}`)} disabled={banningUsers.has(item.userId)}>{banningUsers.has(item.userId) ? 'Aplicando...' : 'Ban global'}</Button></div></li>)}</ul>{persistentCaptchaUsers.length > 20 && <p className="mt-2 text-xs text-rose-600">...y {persistentCaptchaUsers.length - 20} más</p>}</section>}{captchaAppeals.length > 0 && <section className="mt-4 rounded-xl border border-blue-500/30 bg-blue-500/10 p-3"><h3 className="text-sm font-semibold text-blue-700">Solicitudes de apelación de captcha</h3><div className="mt-2 space-y-2 text-xs text-blue-700">{captchaAppeals.slice(0, 20).map((appeal) => <div key={appeal.id || appeal.user_id} className="rounded-lg border border-blue-500/20 p-2"><p className="font-medium">{appeal.user_name || `Usuario ${appeal.user_id}`}</p><p>ID {appeal.user_id} · Motivo: {appeal.reason || 'Sin motivo indicado'}</p><p className="text-muted-foreground">Estado: {appeal.status || 'pending'}</p></div>)}</div>{captchaAppeals.length > 20 && <p className="mt-2 text-xs text-blue-700">...y {captchaAppeals.length - 20} más</p>}</section>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Protección anti-flood</h3><p className="my-2 text-sm text-muted-foreground">Limita ráfagas por usuario, elimina el exceso y aplica mute temporal. Las reincidencias pueden terminar en ban local.</p><div className="mb-3 flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.flood_control?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { flood_control: { enabled: false } } })}>Desactivado</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { flood_control: { enabled: true, messages: 10, window_seconds: 12, mute_minutes: 5, strikes_before_ban: 5, delete_messages: true } } })}>Suave</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { flood_control: { enabled: true, messages: 8, window_seconds: 10, mute_minutes: 10, strikes_before_ban: 3, delete_messages: true } } })}>Equilibrado</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { flood_control: { enabled: true, messages: 5, window_seconds: 8, mute_minutes: 30, strikes_before_ban: 2, delete_messages: true } } })}>Estricto</Button></div>{detail.config.flood_control?.enabled && <p className="text-xs text-muted-foreground">{detail.config.flood_control.messages} mensajes/{detail.config.flood_control.window_seconds}s · mute {detail.config.flood_control.mute_minutes} min · ban tras {detail.config.flood_control.strikes_before_ban || '8'} reincidencias</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Tipos de contenido</h3><p className="my-2 text-sm text-muted-foreground">Decide qué formatos pueden enviar los miembros y limita el tamaño antes de descargar archivos.</p><div className="mb-3 flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.media_controls?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { media_controls: { enabled: false } } })}>Sin restricciones</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { media_controls: { enabled: true, blocked_types: ['sticker', 'animation', 'video_note'], max_file_mb: 25, action: 'delete', mute_minutes: 10, notify: true } } })}>Productivo</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { media_controls: { enabled: true, blocked_types: ['photo', 'video', 'audio', 'voice', 'sticker', 'animation', 'video_note'], max_file_mb: 10, action: 'delete', mute_minutes: 10, notify: true } } })}>Solo texto y documentos</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { media_controls: { enabled: true, blocked_types: ['photo', 'video', 'audio', 'voice', 'document', 'sticker', 'animation', 'video_note'], max_file_mb: 1, action: 'mute', mute_minutes: 15, notify: true } } })}>Solo texto estricto</Button></div>{detail.config.media_controls?.enabled && <p className="text-xs text-muted-foreground">Bloqueados: {detail.config.media_controls.blocked_types.join(', ') || 'ninguno'} · máximo {detail.config.media_controls.max_file_mb} MB · acción {detail.config.media_controls.action}</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Menú de comandos y plugins</h3><p className="my-2 text-sm text-muted-foreground">Registra comandos distintos para usuarios, administradores y master. Puedes aislar plugins únicamente en este grupo.</p><div className="mb-3 grid grid-cols-3 gap-2 text-center text-sm"><div className="rounded-lg border p-2"><b>{detail.command_menu?.public?.length || 0}</b><p>Públicos</p></div><div className="rounded-lg border p-2"><b>{detail.command_menu?.admin?.length || 0}</b><p>Admin</p></div><div className="rounded-lg border p-2"><b>{detail.command_menu?.active_plugins?.length || 0}/{detail.command_menu?.plugins_loaded || 0}</b><p>Plugins activos</p></div></div><div className="mb-3 flex flex-wrap gap-2">{(detail.command_menu?.plugin_names || []).map((name) => { const disabled = detail.config.plugin_controls?.disabled_plugins?.includes(name.toLowerCase()) || detail.config.plugin_controls?.enabled === false; return <Button key={name} size="sm" variant={disabled ? 'outline' : 'default'} onClick={() => { const current = new Set(detail.config.plugin_controls?.enabled === false ? (detail.command_menu?.plugin_names || []).map((item) => item.toLowerCase()) : detail.config.plugin_controls?.disabled_plugins || []); if (disabled) current.delete(name.toLowerCase()); else current.add(name.toLowerCase()); groupAction('save_config', null, { config: { plugin_controls: { enabled: true, disabled_plugins: [...current] } } }); }}>{name.replaceAll('_', ' ')}</Button>; })}</div><div className="mb-3 space-y-1">{(detail.command_menu?.plugin_health || []).filter((item) => item.errors || item.handled).map((item) => <div key={item.name} className={`rounded-lg border p-2 text-xs ${item.circuit_open ? 'border-red-500/40 bg-red-500/10' : item.errors ? 'border-amber-500/40 bg-amber-500/10' : ''}`}><b>{item.name}</b> · {item.handled} ejecuciones · {item.errors} errores · {item.avg_ms} ms{item.last_error && <p className="mt-1 text-muted-foreground">{item.last_error}</p>}</div>)}</div><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { plugin_controls: { enabled: false, disabled_plugins: [] } } })}>Desactivar todos</Button><Button size="sm" onClick={() => groupAction('sync_commands')}>Sincronizar comandos</Button></div>{detail.command_menu?.synced === false && <p className="mt-2 text-xs text-amber-600">Telegram rechazó la sincronización: {(detail.command_menu.errors || []).join(', ')}</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Anuncios entre grupos asociados</h3><p className="my-2 text-sm text-muted-foreground">Controla compatibilidad de audiencia, frecuencia, descanso, límites semanales y pausa por fallos.</p><div className="mb-3 flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.ad_exchange?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { ad_exchange: { enabled: false } } })}>Desactivados</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { ad_exchange: { enabled: true, cooldown_hours: 168, max_daily: 1, max_weekly: 3, pause_after_failures: 2, same_category_priority: true, max_size_ratio: 5 } } })}>Selectivo</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { ad_exchange: { enabled: true, cooldown_hours: 72, max_daily: 2, max_weekly: 6, pause_after_failures: 3, same_category_priority: true, max_size_ratio: 10 } } })}>Equilibrado</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { ad_exchange: { enabled: true, cooldown_hours: 24, max_daily: 4, max_weekly: 15, pause_after_failures: 5, same_category_priority: false, max_size_ratio: 25 } } })}>Amplio</Button></div>{detail.config.ad_exchange?.enabled && <p className="text-xs text-muted-foreground">Máximo {detail.config.ad_exchange.max_daily}/día y {detail.config.ad_exchange.max_weekly}/semana · descanso {detail.config.ad_exchange.cooldown_hours} h · pausa tras {detail.config.ad_exchange.pause_after_failures} fallos · audiencia ×{detail.config.ad_exchange.max_size_ratio}</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Centro de campañas</h3><p className="my-2 text-sm text-muted-foreground">Crea, acepta, cancela y consulta anuncios recíprocos directamente desde TodoSobreAllTech.</p>{!ads ? <Button size="sm" onClick={loadAds}>Abrir campañas</Button> : <div className="space-y-3"><div className="flex max-h-28 flex-wrap gap-2 overflow-auto">{ads.partners?.map((partner) => <Button key={partner.chat_id} size="sm" variant={adTarget === partner.chat_id ? 'default' : 'outline'} onClick={() => setAdTarget(partner.chat_id)}>{partner.favorite && '? '}{partner.name} · {partner.subscribers}</Button>)}</div><textarea className="min-h-24 w-full rounded-md border bg-background p-3 text-sm" value={adText} onChange={(event) => setAdText(event.target.value)} placeholder="Texto del anuncio" maxLength={3500} /><Input type="datetime-local" value={adWhen} onChange={(event) => setAdWhen(event.target.value)} /><Button size="sm" disabled={!adTarget || !adText || !adWhen} onClick={() => adAction('request', { to_chat: adTarget, text: adText, when: new Date(adWhen).toISOString() })}>Solicitar intercambio</Button><div className="max-h-72 space-y-2 overflow-auto">{ads.campaigns?.map((campaign) => <div key={campaign.id} className="rounded-lg border p-3 text-sm"><b>{campaign.from_name} ? {campaign.to_name}</b><p>{campaign.status} · {campaign.deliveries}/2 entregas · {campaign.clicks} clics · {campaign.failures} fallos</p><div className="mt-2 flex gap-2">{campaign.status === 'pending' && campaign.to_chat === selected.id && <Button size="sm" onClick={() => { const text = window.prompt('Escribe el anuncio recíproco'); if (text) adAction('accept', { id: campaign.id, text }); }}>Aceptar</Button>}{['pending', 'countered', 'master_review'].includes(campaign.status) && <Button size="sm" variant="outline" onClick={() => adAction('cancel', { id: campaign.id })}>Cancelar</Button>}</div></div>)}</div></div>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Fuentes RSS del grupo</h3><p className="my-2 text-sm text-muted-foreground">Añade RSS o Atom y decide cuáles publican entradas nuevas automáticamente. La primera lectura no publica artículos antiguos.</p><div className="grid gap-2 md:grid-cols-[1fr_2fr_auto]"><Input value={rssTitle} onChange={(event) => setRssTitle(event.target.value)} placeholder="Nombre opcional" maxLength={120} /><Input value={rssUrl} onChange={(event) => setRssUrl(event.target.value)} placeholder="https://ejemplo.com/feed.xml" type="url" /><Button disabled={!rssUrl.trim()} onClick={() => rssAction('add', { url: rssUrl, title: rssTitle })}>Añadir RSS</Button></div><div className="mt-3 space-y-2">{rss?.feeds?.map((feed) => <div key={feed.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-3"><div className="min-w-0"><b>{feed.title || feed.url}</b><p className="break-all text-xs text-muted-foreground">{feed.url}</p><p className={`text-xs ${feed.last_error ? 'text-red-600' : 'text-muted-foreground'}`}>{feed.last_error || (feed.last_checked_at ? `Comprobado ${new Date(feed.last_checked_at).toLocaleString()}` : 'Sin comprobar')}</p><p className="text-xs text-muted-foreground">Incluye: {(feed.include_keywords || []).join(', ') || 'todo'} · Excluye: {(feed.exclude_keywords || []).join(', ') || 'nada'}{feed.message_thread_id ? ` · tema ${feed.message_thread_id}` : ''}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant={feed.enabled ? 'default' : 'outline'} onClick={() => rssAction('toggle', { feed_id: feed.id, enabled: !feed.enabled })}>{feed.enabled ? 'Activo' : 'Pausado'}</Button><Button size="sm" variant="outline" onClick={() => configureRss(feed)}>Configurar</Button><Button size="sm" variant="outline" onClick={() => rssAction('test', { feed_id: feed.id })}>Probar</Button><Button size="sm" variant="destructive" onClick={() => window.confirm('¿Eliminar este RSS?') && rssAction('delete', { feed_id: feed.id })}>Eliminar</Button></div></div>)}{rss && !rss.feeds?.length && <p className="text-sm text-muted-foreground">Este grupo aún no tiene fuentes RSS.</p>}</div></section>
      <section className="rounded-xl border p-4"><h3 className="mb-3 font-semibold">Rendimiento RSS</h3><div className="grid grid-cols-2 gap-2 text-center text-sm md:grid-cols-4">{[['Comprobaciones', 'checks_count'], ['Publicadas', 'published_count'], ['Filtradas', 'filtered_count'], ['Errores', 'error_count']].map(([label, key]) => <div key={key} className="rounded-lg border p-2"><b>{(rss?.feeds || []).reduce((sum, feed) => sum + (feed[key] || 0), 0)}</b><p className="text-xs text-muted-foreground">{label}</p></div>)}</div><div className="mt-3 space-y-2">{rss?.feeds?.map((feed) => <div key={feed.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg border p-2 text-xs"><span><b>{feed.title || feed.url}</b> · {feed.health || 'disabled'} · {feed.last_duration_ms == null ? 'sin latencia' : `${feed.last_duration_ms} ms`}{feed.next_check_at ? ` · próximo ${new Date(feed.next_check_at).toLocaleString()}` : ''}</span><Button size="sm" variant="outline" onClick={() => window.confirm('¿Reiniciar las métricas de esta fuente?') && rssAction('reset_metrics', { feed_id: feed.id })}>Reiniciar métricas</Button></div>)}</div>{rss?.history?.length > 0 && <details className="mt-3 text-sm"><summary>Historial de entregas ({rss.history.length})</summary><div className="mt-2 max-h-40 space-y-1 overflow-auto">{rss.history.map((item, index) => <p key={`${item.entry_id}-${index}`} className="text-xs text-muted-foreground">{new Date(item.published_at).toLocaleString()} · {item.title || item.source || `fuente ${item.feed_id}`}{item.url && <> · <a className="underline" href={item.url} target="_blank" rel="noreferrer">abrir</a></>}</p>)}</div><Button className="mt-2" size="sm" variant="outline" onClick={() => window.confirm('¿Borrar el historial RSS del grupo?') && rssAction('clear_history')}>Vaciar historial</Button></details>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Reacciones contextuales</h3><p className="my-2 text-sm text-muted-foreground">Moonbot interpreta agradecimientos, humor, celebraciones, dudas y respuestas relacionadas antes de elegir una reacción de Telegram. Evita mensajes sensibles y limita la frecuencia.</p><div className="flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.contextual_reactions?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { contextual_reactions: { enabled: false } } })}>Desactivadas</Button>{[['Selectivo', 'selective', 8, 12], ['Equilibrado', 'balanced', 20, 30], ['Activo', 'active', 40, 15]].map(([label, mode, max, cooldown]) => <Button key={mode} size="sm" variant={detail.config.contextual_reactions?.enabled && detail.config.contextual_reactions?.mode === mode ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { contextual_reactions: { enabled: true, mode, max_per_hour: max, cooldown_seconds: cooldown } } })}>{label}</Button>)}</div>{detail.config.contextual_reactions?.enabled && <p className="mt-2 text-xs text-muted-foreground">Modo {detail.config.contextual_reactions.mode} · máximo {detail.config.contextual_reactions.max_per_hour}/hora · espera {detail.config.contextual_reactions.cooldown_seconds}s · otros bots {detail.config.contextual_reactions.react_to_bots ? 'incluidos' : 'excluidos'}</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="font-semibold">Horario silencioso global</h3><p className="my-2 text-sm text-muted-foreground">Retiene RSS, automatizaciones y publicaciones programadas. Los comandos manuales y las alertas de seguridad continúan funcionando.</p><div className="flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.quiet_hours?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { quiet_hours: { enabled: false } } })}>Desactivado</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { quiet_hours: { enabled: true, start: '23:00', end: '07:00', timezone: 'Europe/Madrid', allowed_categories: ['security', 'moderation'], emergency_bypass: true } } })}>23:00–07:00 Madrid</Button><Button size="sm" variant="outline" onClick={() => groupAction('save_config', null, { config: { quiet_hours: { enabled: true, start: '00:00', end: '08:00', timezone: 'Europe/Madrid', allowed_categories: ['security', 'moderation'], emergency_bypass: true } } })}>00:00–08:00 Madrid</Button></div>{detail.config.quiet_hours?.enabled && <p className="mt-2 text-xs text-muted-foreground">{detail.config.quiet_hours.start}–{detail.config.quiet_hours.end} · {detail.config.quiet_hours.timezone} · excepciones: {(detail.config.quiet_hours.allowed_categories || []).join(', ')}</p>}</section>
      <section className="rounded-xl border border-amber-500/30 p-4"><h3 className="font-semibold">Transcripción segura de voz</h3><p className="my-2 text-sm text-muted-foreground">Solo se activa con consentimiento. Envía temporalmente la nota de voz a OpenAI, la elimina al terminar y nunca la incorpora al aprendizaje automático.</p><div className="flex flex-wrap gap-2"><Button size="sm" variant={!detail.config.voice_transcription?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { voice_transcription: { enabled: false } } })}>Desactivada</Button><Button size="sm" variant={detail.config.voice_transcription?.enabled ? 'default' : 'outline'} onClick={() => groupAction('save_config', null, { config: { voice_transcription: { enabled: true, provider: 'openai', model: 'whisper-1', language: '', consent_notice: true, learn_from_transcript: false } } })}>Activar con consentimiento</Button></div><p className="mt-2 text-xs text-muted-foreground">Máximo 20 MiB y 10 minutos · borrado obligatorio · sin texto simulado.</p></section>
      <section className="rounded-xl border p-4"><h3 className="mb-3 font-semibold">Módulos activos</h3><div className="flex flex-wrap gap-2">{Object.entries(detail.config).filter(([, value]) => value && typeof value === 'object' && value.enabled).map(([name]) => <Badge key={name}>{name.replaceAll('_', ' ')}</Badge>)}</div></section>
      <section className="rounded-xl border p-4"><h3 className="mb-1 font-semibold">Auditoría de cambios sensibles</h3><p className="mb-3 text-sm text-muted-foreground">Cambios efectivos de seguridad y moderación realizados desde la web, la MiniApp o una importación.</p><div className="max-h-72 space-y-2 overflow-auto">{detail.sensitive_changes?.map((event) => <div key={event.id} className="rounded-lg border bg-background/70 p-3 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><b>{event.risk === 'critical' ? '🔴 Crítico' : '🟠 Alto'} · {event.source || 'sistema'}</b><small>{new Date(event.created_at).toLocaleString()}</small></div><p className="text-xs text-muted-foreground">Autor: {event.actor || 'sistema'}</p><div className="mt-2 flex flex-wrap gap-1">{event.changes?.map((change, index) => <Badge key={`${event.id}-${index}`} variant="outline">{change.section}.{change.field}</Badge>)}</div></div>)}{!detail.sensitive_changes?.length && <p className="text-sm text-muted-foreground">Todavía no hay cambios sensibles registrados.</p>}</div></section>
      <section className="rounded-xl border p-4"><h3 className="mb-3 font-semibold">Copiar o comparar reglas</h3><div className="space-y-2">{groups.filter((group) => group.id !== selected.id).slice(0, 12).map((group) => <div key={group.id} className="flex items-center justify-between"><span className="text-sm">{group.name}</span><span className="flex gap-2"><Button size="sm" variant="outline" onClick={() => groupAction('compare_config', group.id)}>Comparar</Button><Button size="sm" variant="outline" onClick={() => groupAction('copy_config', group.id)}>Copiar</Button></span></div>)}</div>{comparison && <p className="mt-3 rounded-lg bg-muted/40 p-3 text-sm">{comparison.identical ? 'Configuraciones idénticas.' : `${comparison.differences.length} diferencias: ${comparison.differences.map((item) => item.section).join(', ')}`}</p>}</section>
      <section className="rounded-xl border p-4"><h3 className="mb-3 font-semibold">Historial reciente</h3><div className="max-h-64 space-y-2 overflow-auto">{detail.history?.map((item, index) => <div key={`${item.time}-${index}`} className="rounded-lg border p-2 text-sm"><b>{item.sender}</b> <small>{item.time}</small><p>{item.text || (item.has_media ? 'Contenido multimedia' : '')}</p></div>)}{!detail.history?.length && <p className="text-sm text-muted-foreground">No hay historial almacenado.</p>}</div></section>
      {isChannelView && <section className="rounded-xl border border-amber-400/40 p-4"><h3 className="font-semibold">Suscripciones de pago oficiales</h3><p className="my-2 text-sm text-muted-foreground">Crea enlaces oficiales de Telegram para dar acceso al canal a cambio de Telegram Stars. Telegram renueva el acceso cada 30 días.</p><div className="grid gap-2 md:grid-cols-[1fr_180px_auto]"><Input value={paidSubscriptionName} onChange={(event) => setPaidSubscriptionName(event.target.value)} placeholder="Nombre interno" maxLength={32} /><Input value={paidSubscriptionPrice} onChange={(event) => setPaidSubscriptionPrice(event.target.value)} type="number" min="1" max="10000" placeholder="Stars/mes" /><Button disabled={!paidSubscriptionName.trim() || Number(paidSubscriptionPrice) < 1 || Number(paidSubscriptionPrice) > 10000} onClick={() => paidSubscriptionAction('create', { name: paidSubscriptionName.trim(), subscription_price: Number(paidSubscriptionPrice) })}>Crear enlace</Button></div><p className="mt-2 text-xs text-muted-foreground">Precio permitido: 1–10.000 ⭐ al mes. Para cambiar el precio debes revocar el enlace y crear otro.</p><div className="mt-3 space-y-2">{paidSubscriptions?.links?.map((link) => <div key={link.invite_link} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-3"><div className="min-w-0"><b>{link.name || 'Suscripción mensual'}</b><p className="text-sm">{link.subscription_price} ⭐ / 30 días · {link.is_revoked ? 'Revocado' : 'Activo'}</p><p className="max-w-xl truncate text-xs text-muted-foreground">{link.invite_link}</p></div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" disabled={link.is_revoked} onClick={() => navigator.clipboard.writeText(link.invite_link)}>Copiar</Button><Button size="sm" variant="outline" disabled={link.is_revoked} onClick={() => { const name = window.prompt('Nuevo nombre interno (máximo 32 caracteres)', link.name || ''); if (name !== null) paidSubscriptionAction('rename', { invite_link: link.invite_link, name }); }}>Renombrar</Button><Button size="sm" variant="destructive" disabled={link.is_revoked} onClick={() => window.confirm('¿Revocar este enlace de suscripción?') && paidSubscriptionAction('revoke', { invite_link: link.invite_link })}>Revocar</Button></div></div>)}{paidSubscriptions && !paidSubscriptions.links?.length && <p className="text-sm text-muted-foreground">El bot aún no ha creado enlaces de pago para este canal.</p>}</div></section>}
    </>}
  </CardContent></Card>;
};

export default MoonbotGroupsManager;


